export const MC_CLASSE = dec('');
export const MC_LUZ = dec('');
export const MC_POR_NOME = new Map(MC_BLOCOS.map((b, i) => [b.n, i]));
// estado → índice do bloco em MC_BLOCOS (busca binária no primeiro estado)
export function mcBloco(n) { let lo = 0, hi = MC_BLOCOS.length - 1; while (lo < hi) { const m = (lo + hi + 1) >> 1; if (MC_BLOCOS[m].s <= n) lo = m; else hi = m - 1; } return lo; }
// estado → { nome, props }; e o caminho inverso
export function mcEstado(n) {
  const b = MC_BLOCOS[mcBloco(n)]; let r = n - b.s; const props = {};
  for (let i = b.p.length - 1; i >= 0; i--) { const [k, vs] = b.p[i]; props[k] = vs[r % vs.length]; r = Math.floor(r / vs.length); }
  return { nome: b.n, props };
}
export function mcNumero(nome, props = {}) {
  const i = MC_POR_NOME.get(nome); if (i === undefined) return -1;
  const b = MC_BLOCOS[i]; let r = 0;
  for (const [k, vs] of b.p) { const j = Math.max(0, vs.indexOf(String(props[k] ?? vs[0]))); r = r * vs.length + j; }
  return b.s + r;
}
